import{_ as s,C as d,o as t,c as i,a5 as r,b as c,w as o,a as n,E as l,a7 as E}from"./chunks/framework.QWVCgkrI.js";const _=JSON.parse('{"title":"Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ","description":"","frontmatter":{"title":"Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"git restoreの復元元と復元先の既定値を読み、HEADやブランチを動かさずに指定パスのindex・作業ツリーを更新する仕組みを確認する。","aliases":["Git restore","復元元","復元先","git restore --staged","ステージ解除"],"verification":"Git公式資料と照合し、Windowsの独立リポジトリで既定値と指定元の組み合わせを確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-restore.md","filePath":"tools/git-restore.md"}'),h={name:"tools/git-restore.md"};function g(p,e,A,m,u,f){const a=d("Mermaid");return t(),i("div",null,[e[1]||(e[1]=r('<h1 id="git-restoreの仕組み-—-履歴を動かさず、復元元と復元先を選ぶ" tabindex="-1">Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ <a class="header-anchor" href="#git-restoreの仕組み-—-履歴を動かさず、復元元と復元先を選ぶ" aria-label="Permalink to &quot;Git restoreの仕組み — 履歴を動かさず、復元元と復元先を選ぶ&quot;">​</a></h1><p>敵のHPが、最後のコミットでは20、ステージ済みの版では30、編集中のファイルでは40だとします。<code>git restore</code> でそのファイルを指定するだけなら、編集中のHPは30になります。ステージ済みの版を復元元にするためです。<a href="https://git-scm.com/docs/git-restore#_description" target="_blank" rel="noreferrer">Git公式のrestoreマニュアル</a></p><h2 id="パス・復元元・復元先を決める" tabindex="-1">パス・復元元・復元先を決める <a class="header-anchor" href="#パス・復元元・復元先を決める" aria-label="Permalink to &quot;パス・復元元・復元先を決める&quot;">​</a></h2><p><code>git restore</code> は、指定したパスを、復元元の内容に合わせて復元先で更新します。復元先にできるのは、次のコミットの内容を用意するindexと、いま編集している作業ツリーです。<code>HEAD</code> は復元元になり得ます。操作したリポジトリのブランチの先端と、<code>HEAD</code> が指すコミットはrestoreの前後で同じです。<a href="/study/tools/git-staging-index.html">Gitのステージング</a> · <a href="https://git-scm.com/docs/git#_reset_restore_and_revert" target="_blank" rel="noreferrer">Git公式のreset・restore・revertの比較</a></p><p>図は <code>--source</code> を省略したときの流れです。復元先としてindexを指定する <code>--staged</code> には、既定の復元元を <code>HEAD</code> に変える働きもあります。</p>',5)),(t(),c(E,null,{default:o(()=>[l(a,{id:"mermaid-15",class:"mermaid",graph:"---%0Aconfig%3A%0A%20%20flowchart%3A%0A%20%20%20%20nodeSpacing%3A%2016%0A%20%20%20%20rankSpacing%3A%2042%0A%20%20%20%20padding%3A%208%0A---%0Aflowchart%20TD%0A%20%20%20%20accTitle%3A%20git%20restore%E3%81%A7%E5%BE%A9%E5%85%83%E5%85%83%E3%82%92%E7%9C%81%E7%95%A5%E3%81%97%E3%81%9F%E5%A0%B4%E5%90%88%E3%81%AE%E3%83%87%E3%83%BC%E3%82%BF%E3%81%AE%E6%B5%81%E3%82%8C%0A%20%20%20%20accDescr%3A%20%E5%BE%A9%E5%85%83%E5%85%88%E3%82%92%E6%8C%87%E5%AE%9A%E3%81%97%E3%81%AA%E3%81%84%E5%A0%B4%E5%90%88%E3%81%8Bworktree%E3%81%A0%E3%81%91%E3%82%92%E6%8C%87%E5%AE%9A%E3%81%97%E3%81%9F%E5%A0%B4%E5%90%88%E3%80%81index%E3%81%8B%E3%82%89%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%81%B8%E3%80%82staged%E3%81%A0%E3%81%91%E3%81%AA%E3%82%89HEAD%E3%81%8B%E3%82%89index%E3%81%B8%E3%80%82%E4%B8%A1%E6%96%B9%E3%81%AA%E3%82%89HEAD%E3%81%8B%E3%82%89index%E3%81%A8%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%E3%81%AE%E4%B8%A1%E6%96%B9%E3%81%B8%E3%80%82%0A%20%20%20%20idx%5B%22%E5%BE%A9%E5%85%83%E5%85%83%20index%22%5D%20--%3E%7C%E7%9C%81%E7%95%A5%E3%81%8B%20worktree%7C%20wt%5B%22%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%22%5D%0A%20%20%20%20head%5B%22%E5%BE%A9%E5%85%83%E5%85%83%20HEAD%22%5D%20--%3E%7Cstaged%7C%20stage%5B%22index%22%5D%0A%20%20%20%20head%20--%3E%7C%E4%B8%A1%E6%96%B9%E3%82%92%E6%8C%87%E5%AE%9A%7C%20both%5B%22index%20%E3%81%A8%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%AA%E3%83%BC%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r(`<ul><li>復元先を省略するか <code>--worktree</code> だけを指定すると、既定の復元元は <strong>index</strong> です。</li><li><code>--staged</code> だけを指定すると、既定では <strong>HEADからindex</strong> へ写します。作業ファイルには手を加えません。</li><li><code>--staged --worktree</code> を指定すると、既定では <strong>HEADから両方</strong> に写します。</li><li><code>--source</code> では、コミットやタグなどが指すツリーを復元元に指定できます。復元先は引き続き <code>--staged</code> と <code>--worktree</code> で決まります。<a href="https://git-scm.com/docs/git-restore#_options" target="_blank" rel="noreferrer">Git公式のrestoreオプション</a></li></ul><h2 id="同じファイルを、どの版からどこへ戻すか" tabindex="-1">同じファイルを、どの版からどこへ戻すか <a class="header-anchor" href="#同じファイルを、どの版からどこへ戻すか" aria-label="Permalink to &quot;同じファイルを、どの版からどこへ戻すか&quot;">​</a></h2><p><code>enemy.txt</code> が <code>hp=10</code> のコミットAの次に、<code>hp=20</code> のコミットBを作り、<code>main</code> の先端をBにしました。同じファイルを <code>hp=30</code> にしてステージしてから、作業ツリーだけ <code>hp=40</code> に編集しました。次の表は、この初期状態を用意した別々の使い捨てリポジトリで、各オプションを実行したあとのHPです。対象は <code>enemy.txt</code> で、すべての行で <code>HEAD</code> はHP20のBを指します。Aを復元元にする例では <code>--source=a57b882</code> を使いました。</p><table tabindex="0"><thead><tr><th>オプション</th><th>index</th><th>作業ツリー</th></tr></thead><tbody><tr><td>省略、または<br><code>--worktree</code></td><td>30</td><td>30</td></tr><tr><td><code>--staged</code></td><td>20</td><td>40</td></tr><tr><td><code>--staged</code><br><code>--worktree</code></td><td>20</td><td>20</td></tr><tr><td>Aを <code>--source</code> に指定<br><code>--worktree</code></td><td>30</td><td>10</td></tr><tr><td>Aを <code>--source</code> に指定<br><code>--staged</code><br><code>--worktree</code></td><td>10</td><td>10</td></tr></tbody></table><p>オプションなしで <code>git restore -- enemy.txt</code> を実行した直後の出力です。<code>70e721f</code> が元の先端Bです。<code>git show &#39;:enemy.txt&#39;</code> はindexから読み、PowerShellの <code>Get-Content</code> は作業ファイルを読みます。<a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式のリビジョン指定</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; git rev-parse --short HEAD</span></span>
<span class="line"><span>70e721f</span></span>
<span class="line"><span>PS&gt; git show &#39;:enemy.txt&#39;</span></span>
<span class="line"><span>hp=30</span></span>
<span class="line"><span>PS&gt; Get-Content -LiteralPath enemy.txt</span></span>
<span class="line"><span>hp=30</span></span></code></pre></div><p>この例では、先端BのHP20に対して、indexにはHP30の変更が残っています。作業ツリーとindexはともにHP30なので、未ステージのHP40はなくなりました。<code>--staged</code> だけを使った例では、HP40が作業ファイルに残り、HEADのHP20がindexに入りました。<a href="https://git-scm.com/docs/git-restore#_description" target="_blank" rel="noreferrer">Git公式のrestoreマニュアル</a></p><h2 id="上書きした変更をどこまで探せるか" tabindex="-1">上書きした変更をどこまで探せるか <a class="header-anchor" href="#上書きした変更をどこまで探せるか" aria-label="Permalink to &quot;上書きした変更をどこまで探せるか&quot;">​</a></h2><p>復元先に変更があれば、その内容は復元元の内容で上書きされます。追跡対象のパスが復元元に存在しない場合は、既定ではそのパスを復元先から取り除いて元に合わせます。たとえば新しいファイルをステージしたあと、そのパスのindexを <code>HEAD</code> から復元すると、<code>HEAD</code> にそのパスがなければindexから外れます。作業ファイルは残り、未追跡になります。この削除条件は公式資料で確認しました。<a href="https://git-scm.com/docs/git-restore#_description" target="_blank" rel="noreferrer">Git公式のrestoreマニュアル</a></p><p>この検証でHP40は作業ツリーにしかなく、対応するblobはGitのオブジェクトデータベースにありませんでした。作業ツリーをHP30に上書きしたあと、以前のHP40をreflogから取り出すことはできません。別の <code>--staged</code> の例では、HP30がindexから外れたあとも、<code>git add</code> で作られたblobが残りました。ステージした版を後から探し出せるかは、オブジェクトが残っているかどうかなどに依存します。reflogが記録するのは参照の移動です。<a href="/study/tools/git-reflog.html">Gitのreflog</a> · <a href="https://git-scm.com/docs/user-manual#dangling-objects" target="_blank" rel="noreferrer">Git User Manualのdangling objects</a></p><h2 id="reset・revertとの関係" tabindex="-1">reset・revertとの関係 <a class="header-anchor" href="#reset・revertとの関係" aria-label="Permalink to &quot;reset・revertとの関係&quot;">​</a></h2><p>コミットを指定する <code>reset</code> は、ブランチの先端を指定のコミットへ動かし、モードによってindexや作業ツリーも更新します。パスを指定する <code>reset</code> は、<code>restore --staged</code> と同じく、指定パスのindexを更新する使い方があります。<code>revert</code> は変更を打ち消す新しいコミットを作ります。<code>restore</code> で作業ファイルやindexを更新した結果を履歴に残すときは、その結果を別にコミットします。<a href="https://git-scm.com/docs/git#_reset_restore_and_revert" target="_blank" rel="noreferrer">Git公式のreset・restore・revertの比較</a> · <a href="/study/tools/git-reset.html">Gitのreset</a> · <a href="/study/tools/git-revert.html">Gitのrevert</a></p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>HP20をコミットしたあと、HP30をステージし、HP40に再編集した。オプションを省いたrestoreで作業ファイルはどの値になる？</summary><p>HP30です。既定ではindexから作業ツリーへ写します。</p></details><details class="details custom-block"><summary><code>--staged --worktree</code> を指定し、<code>--source</code> を省略した。indexと作業ファイルはどこから戻る？</summary><p>両方ともHEADから復元されます。この例ではHP20です。</p></details><details class="details custom-block"><summary><code>--source</code> に古いコミットを指定したら、ブランチの先端も古いコミットへ移る？</summary><p>ブランチの先端はそのままです。古いコミットのツリーは復元元として読まれます。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日に、WindowsのGit 2.39.2.windows.1と独立したSHA-1リポジトリ6つを使いました。<code>main</code> 上の追跡テキスト1ファイルで、表の組み合わせを実行しました。各実行前後で、<code>main</code> と <code>HEAD</code> の参照先、コミット履歴、indexと作業ファイルの内容を比較しました。復元元にパスがない場合は公式資料に基づく説明です。競合中のindex、<code>--patch</code>、サブモジュール、スパースチェックアウトは実行していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-staging-index.html">Gitのステージング</a> — HEAD・index・作業ツリーの内容を比べる。</li><li><a href="/study/tools/git-reset.html">Gitのreset</a> — コミットを指定した形式とパスを指定した形式を比べる。</li><li><a href="/study/tools/git-revert.html">Gitのrevert</a> — 履歴に変更を打ち消した記録を残す仕組みを読む。</li><li><a href="/study/tools/git-reflog.html">Gitのreflog</a> — 参照の移動の記録で探せる範囲を確認する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-restore" target="_blank" rel="noreferrer">Git公式 — git-restore</a></li><li><a href="https://git-scm.com/docs/git#_reset_restore_and_revert" target="_blank" rel="noreferrer">Git公式 — Reset, restore and revert</a></li><li><a href="https://git-scm.com/docs/gitrevisions" target="_blank" rel="noreferrer">Git公式 — gitrevisions</a></li><li><a href="https://git-scm.com/docs/user-manual#dangling-objects" target="_blank" rel="noreferrer">Git User Manual — Dangling objects</a></li></ul>`,22))])}const x=s(h,[["render",g]]);export{_ as __pageData,x as default};
